# durum geçmişi (DurumOlayi), tür eşleştirmeleri veritabanında (bürodaki tüm
# bilgisayarlar ortak görür; yerel JSON ilk açılışta tur_eslestirme aktarır).

import json

from django.db import migrations, models

from icra_models.tarih import tarih_coz

_YER = ("islem_yeri", "merkez", "sube", "ilce", "il")


def hareketleri_doldur(apps, schema_editor):
    TB = apps.get_model("icra_models", "TebligatBarkod")
    PH = apps.get_model("icra_models", "PttHareket")
    toplu = []
    for tb_id, ham in TB.objects.exclude(ham_yanit__isnull=True).values_list("id", "ham_yanit").iterator():
        if isinstance(ham, str):
            try:
                ham = json.loads(ham)
            except ValueError:
                continue
        if not isinstance(ham, dict) or ham.get("_hata"):
            continue
        for i, h in enumerate(h for h in (ham.get("hareketDongu") or []) if isinstance(h, dict)):
            tarih = str(h.get("tarih") or "").strip()
            saat = str(h.get("saat") or "").strip()
            yer = " / ".join(dict.fromkeys(str(h.get(k)).strip() for k in _YER if str(h.get(k) or "").strip()))
            toplu.append(PH(tebligat_id=tb_id, sira=i, zaman=tarih_coz(f"{tarih} {saat}".strip()),
                            aciklama=str(h.get("aciklama") or "")[:255], yer=yer[:255],
                            islem_detay=str(h.get("islem_detay") or "")[:255], ham=h))
        if len(toplu) >= 2000:
            PH.objects.bulk_create(toplu)
            toplu = []
    if toplu:
        PH.objects.bulk_create(toplu)


def _kisitlar_hemen(apps, schema_editor):
    """PostgreSQL: veri adımından kalan ertelenmiş FK denetimleri, Django'nun
    migration sonunda kurduğu index'leri "pending trigger events" ile
    düşürmesin diye hemen çalıştırılır (SQLite'ta etkisiz)."""
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


